mapper.select:
SELECT al.id, al.pass_code_id, al.visitor_id, v.name AS visitorName, al.appointment_id, a.appoint_no AS appointmentNo, al.action, al.gate_location, al.result, al.deny_reason, al.operator_id, al.gate_id AS gateId, al.area_id AS areaId, g.name AS gateName, ar.name AS areaName, al.created_at FROM access_log al LEFT JOIN visitor v ON al.visitor_id = v.id LEFT JOIN appointment a ON al.appointment_id = a.id LEFT JOIN gate g ON al.gate_id = g.id LEFT JOIN area ar ON al.area_id = ar.id
AND al.visitor_id = #{visitorId}
AND al.appointment_id = #{appointmentId}
ORDER BY al.created_at DESC
